import{_ as r,C as n,o as t,c as s,a2 as a,b as l,w as i,a as d,E as c,a3 as h}from"./chunks/framework.CZqXuAiL.js";const b=JSON.parse(`{"title":"Fall-Check Verification","description":"NitroCord's fall-check client verification deep dive — the fake void world, the vanilla gravity table, the trap platform, failure reasons, lag tolerance, and tuning guidance for real players.","frontmatter":{"title":"Fall-Check Verification","description":"NitroCord's fall-check client verification deep dive — the fake void world, the vanilla gravity table, the trap platform, failure reasons, lag tolerance, and tuning guidance for real players."},"headers":[],"relativePath":"nitrocord/architecture/verification.md","filePath":"nitrocord/architecture/verification.md","lastUpdated":null}`),f={name:"nitrocord/architecture/verification.md"};function p(u,e,m,k,g,v){const o=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="fall-check-verification" tabindex="-1">Fall-Check Verification <a class="header-anchor" href="#fall-check-verification" aria-label="Permalink to &quot;Fall-Check Verification&quot;">​</a></h1><blockquote><p><strong>Bots can fake a handshake. They cannot fake physics.</strong> The fall check holds each joining client inside a tiny void world on the proxy and makes it prove it is a real Minecraft client the one way a bot cannot cheaply imitate: by falling with exact vanilla gravity and landing on a platform it could not have predicted.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#what-the-fall-check-is">What the fall check is</a></li><li><a href="#the-verification-flow">The verification flow</a></li><li><a href="#why-bots-fail-it">Why bots fail it</a></li><li><a href="#failure-reasons">Failure reasons</a></li><li><a href="#the-honest-caveat-lag-costs-a-reset-not-a-kick">The honest caveat: lag costs a reset, not a kick</a></li><li><a href="#tuning-guidance">Tuning guidance</a><ul><li><a href="#verify-max-time-ms-default-30000">verify.max-time-ms (default 30000)</a></li><li><a href="#verify-only-during-attack-default-false">verify.only-during-attack (default false)</a></li><li><a href="#verify-spawn-height-default-200">verify.spawn-height (default 200)</a></li><li><a href="#geyser-behavior">Geyser behavior</a></li><li><a href="#the-verified-whitelist-integration">The verified-whitelist integration</a></li></ul></li><li><a href="#related-pages">Related pages</a></li></ul></nav><hr><h2 id="what-the-fall-check-is" tabindex="-1">What the fall check is <a class="header-anchor" href="#what-the-fall-check-is" aria-label="Permalink to &quot;What the fall check is&quot;">​</a></h2><p>Handshake-level checks (rate limits, reconnect verification, name heuristics) all judge a connection by what it <em>says</em>. The fall check judges it by what it <em>does</em>. A joining client that passed the login gates is not connected to a backend server. Instead the proxy:</p><ol><li>spawns it into a synthesized void world — a 5×5 empty-chunk area with a plains biome, generated once per protocol version and served from memory;</li><li>stands it on a single support block at <code>verify.spawn-height</code> (default 200);</li><li>removes the support and watches it fall, tick by tick;</li><li>midway through the fall, places a <strong>trap platform</strong> at a pseudo-random height and requires the client to land on it at exactly the tick vanilla physics predicts.</li></ol><p>Every movement packet the client sends is compared against a precomputed table of vanilla fall speeds. A real client passes without knowing anything happened — the whole check takes a few seconds and looks like an odd spawn. A bot must implement the full Minecraft fall integrator, react to a block change it could not precompute, and report its position honestly 20 times a second. Flood tools do none of that.</p><p>The check runs on protocols <strong>47 through 776</strong> (Minecraft 1.8 through 26.2); clients outside that range skip it silently, as do Bedrock players (see <a href="#geyser-behavior">Geyser behavior</a>) and addresses already on the <a href="#the-verified-whitelist-integration">verified-IP whitelist</a>.</p><hr><h2 id="the-verification-flow" tabindex="-1">The verification flow <a class="header-anchor" href="#the-verification-flow" aria-label="Permalink to &quot;The verification flow&quot;">​</a></h2>',11)),(t(),l(h,null,{default:i(()=>[c(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20L(%5BLogin%20completed%5D)%20--%3E%20G%7B%22Verification%20gate%22%7D%0A%20%20%20%20G%20--%3E%7C%22unlicensed%2C%20disabled%2C%3Cbr%2F%3Eonly-during-attack%20%26%20calm%22%7C%20V0%5B%22Vanilla%20flow%3Cbr%2F%3E(no%20check)%22%5D%0A%20%20%20%20G%20--%3E%7C%22whitelisted%20address%22%7C%20V0%0A%20%20%20%20G%20--%3E%7C%22Geyser%20player%20%26%20geyser-skip%22%7C%20V0%0A%20%20%20%20G%20--%3E%7C%22protocol%20outside%2047%E2%80%93776%22%7C%20V0%0A%20%20%20%20G%20--%3E%7C%22verify%22%7C%20C%7B%22Client%20era%3F%22%7D%0A%20%20%20%20C%20--%3E%7C%221.20.2%2B%22%7C%20FC%5B%22Fake%20CONFIG%20phase%3Cbr%2F%3Eregistries%20%C2%B7%20features%20%C2%B7%20finish%22%5D%0A%20%20%20%20FC%20--%3E%20W%0A%20%20%20%20C%20--%3E%7C%22pre-1.20.2%22%7C%20W%5B%22Spawn%20in%20fake%20void%20world%3Cbr%2F%3Esupport%20block%20at%20spawn-height%22%5D%0A%20%20%20%20W%20--%3E%20T%5B%22Teleport%20confirmed%3Cbr%2F%3Esupport%20block%20removed%22%5D%0A%20%20%20%20T%20--%3E%20F%7B%22Fall%20check%3Cbr%2F%3Eper-tick%20speed%20vs%20gravity%20table%22%7D%0A%20%20%20%20F%20--%3E%7C%22speed%20mismatch%22%7C%20R%7B%22Free%20resets%20left%3F%3Cbr%2F%3Emax-free-resets%22%7D%0A%20%20%20%20R%20--%3E%7C%22yes%22%7C%20RS%5B%22Reset%20to%20support%2C%3Cbr%2F%3Efresh%20trap%2C%20clock%20keeps%20running%22%5D%0A%20%20%20%20RS%20--%3E%20W%0A%20%20%20%20R%20--%3E%7C%22no%22%7C%20X1%5B%22kick-verify-failed%3Cbr%2F%3E%2B%20violation%20strike%22%5D%0A%20%20%20%20F%20--%3E%7C%22trap%20placed%20mid-fall%3Cbr%2F%3Eat%20random%20Y%22%7C%20P%7B%22Lands%20on%20platform%3Cbr%2F%3Eat%20the%20predicted%20tick%3F%22%7D%0A%20%20%20%20P%20--%3E%7C%22no%22%7C%20X1%0A%20%20%20%20P%20--%3E%7C%22yes%22%7C%20WC%7B%22Wall%20clock%20%E2%89%A5%3Cbr%2F%3Eticks%20%C3%97%2050%20ms%20%E2%88%92%20500%20ms%3F%22%7D%0A%20%20%20%20WC%20--%3E%7C%22too%20fast%20%E2%80%94%20replayed%22%7C%20X1%0A%20%20%20%20WC%20--%3E%7C%22pass%22%7C%20PA%5B%22Address%20marked%20verified%22%5D%0A%20%20%20%20PA%20--%3E%20BE%5B%22PostLoginEvent%20fires%2C%3Cbr%2F%3Evanilla%20connect%20to%20backend%22%5D%0A%20%20%20%20F%20-.-%3E%7C%22no%20movement%2010%20ticks%22%7C%20X1%0A%20%20%20%20L%20-.-%3E%7C%22max-time-ms%20exceeded%22%7C%20X2%5B%22kick-verify-timeout%3Cbr%2F%3E%2B%20violation%20strike%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>Two details the diagram compresses:</p><ul><li><strong>1.20.2+ clients</strong> land in the CONFIG state after login, so the verification first walks them through a minimal fake configuration (dimension/biome registries, the vanilla feature flag) before entering PLAY — the same exchange a real backend would perform. The <code>verify.max-time-ms</code> budget already runs during this phase, so a client that stalls the configuration is kicked by the same timeout.</li><li><strong>Plugins never see the fake world.</strong> <code>PostLoginEvent</code> and the initial-server connect are deferred until the client passes and the connection is back in a fully vanilla state (a fresh PLAY handler pre-1.20.2, the stock CONFIG handler on 1.20.2+). A plugin observing the player cannot tell the check happened.</li></ul><hr><h2 id="why-bots-fail-it" tabindex="-1">Why bots fail it <a class="header-anchor" href="#why-bots-fail-it" aria-label="Permalink to &quot;Why bots fail it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Defense</th><th>What it catches</th></tr></thead><tbody><tr><td>Vanilla gravity table</td><td>The per-tick fall speed must match <code>v = (v − 0.08) × 0.98</code> integrated exactly as the client does, normalized to two decimals on both sides. Bots that approximate, teleport, or send constant speeds mismatch within a few ticks.</td></tr><tr><td>Trap platform</td><td>At a pseudo-random mid-fall tick a platform of a random block appears at a random Y (8–100, always ≥ 16 below spawn). The client must report <code>y == platformY + 1</code> with <code>onGround</code> at exactly the predicted landing tick — impossible to precompute, and a one-tick grace covers clients that split the landing across two packets.</td></tr><tr><td>Wall-clock anti-precompute</td><td>The fall must have taken at least <code>ticks × 50 ms − 500 ms</code> of real time. A bot that replays a recorded fall at full speed, or answers every check instantly, fails even with perfect positions.</td></tr><tr><td>Zero-movement watchdog</td><td>More than ten consecutive ticks without movement fails — recordings freeze or loop the same frame.</td></tr><tr><td>Fresh state per attempt</td><td>Trap height, trap block, teleport id and timing are re-rolled per attempt, and free resets deliberately do <strong>not</strong> restart the wall clock — resets can never be farmed to bypass the too-fast check.</td></tr></tbody></table><p>On top of the fall itself, <a href="/pingless-studios-docs/nitrocord/configuration/reference#invariants">session invariants</a> challenge the login/config stages with boot-random keep-alive and transaction ids: unsolicited or mismatched answers kick with <code>kick-verify-failed</code>, and a challenge left unanswered for 12 seconds kicks with <code>kick-verify-timeout</code>.</p><hr><h2 id="failure-reasons" tabindex="-1">Failure reasons <a class="header-anchor" href="#failure-reasons" aria-label="Permalink to &quot;Failure reasons&quot;">​</a></h2><p>Both kick messages are configurable under <code>[messages]</code> in <code>nitrocord.toml</code>, and every failure also records a violation strike — repeat offenders escalate from a kick to a firewall ban at <code>[violations] to-blacklist</code> (default 3).</p><table tabindex="0"><thead><tr><th>Kick message</th><th>Logged detail</th><th>What it means</th></tr></thead><tbody><tr><td><code>kick-verify-failed</code></td><td><code>non-vanilla gravity</code></td><td>The per-tick fall speed did not match the physics table after the free resets were used up. The classic bot outcome.</td></tr><tr><td><code>kick-verify-failed</code></td><td><code>fell through the platform</code></td><td>The client passed the platform&#39;s Y without reporting a landing — it either ignored the block change or its physics drifted.</td></tr><tr><td><code>kick-verify-failed</code></td><td><code>did not land on the platform</code></td><td>The client reached the platform top but never reported <code>onGround</code> (after the one-tick grace).</td></tr><tr><td><code>kick-verify-failed</code></td><td><code>no movement while falling</code></td><td>Ten consecutive zero-movement ticks mid-fall — a frozen or looping recording.</td></tr><tr><td><code>kick-verify-failed</code></td><td><code>inhumanly fast fall</code></td><td>Correct positions delivered faster than real time allows — a replayed or precomputed fall.</td></tr><tr><td><code>kick-verify-timeout</code></td><td><code>verification timed out</code> / <code>configuration timed out</code></td><td>The whole check (including the fake CONFIG phase on 1.20.2+) exceeded <code>verify.max-time-ms</code>. Very slow or stalled clients land here, which is why the budget is generous.</td></tr></tbody></table><p>A player who is kicked can simply rejoin: nothing is firewalled on the first failure, and the reconnect check already treats them as a returning visitor.</p><hr><h2 id="the-honest-caveat-lag-costs-a-reset-not-a-kick" tabindex="-1">The honest caveat: lag costs a reset, not a kick <a class="header-anchor" href="#the-honest-caveat-lag-costs-a-reset-not-a-kick" aria-label="Permalink to &quot;The honest caveat: lag costs a reset, not a kick&quot;">​</a></h2><p>The check is deliberately lag-tolerant, and you should know exactly how before sizing it for your audience:</p><ul><li>The <strong>first</strong> gravity mismatch never fails. It consumes one of <code>verify.max-free-resets</code> (default <strong>1</strong>): the client is teleported back onto the support block and restarts the fall with a fresh trap. A player whose connection stutters mid-fall gets a free do-over.</li><li>Only a mismatch <strong>after the free resets are gone</strong> produces <code>kick-verify-failed</code>. So a laggy player pays one extra fall, not their connection.</li><li>The landing check has a one-tick grace for clients that report the position and the on-ground flag in separate packets.</li><li>The two-decimal normalization on the speed comparison absorbs ordinary floating-point and timing noise — real clients do not need perfect ticks.</li></ul><div class="warning custom-block"><p class="custom-block-title">Tune resets, not strictness</p><p>If players on genuinely bad connections (mobile hotspots, transcontinental links) report verification kicks, raise <code>verify.max-free-resets</code> to <code>2</code>–<code>3</code> and <code>verify.max-time-ms</code> above the 30-second default before considering disabling the check. Free resets cannot be abused: the wall clock keeps running across them, so extra attempts only ever make a replayed fall slower — never more convincing.</p></div><hr><h2 id="tuning-guidance" tabindex="-1">Tuning guidance <a class="header-anchor" href="#tuning-guidance" aria-label="Permalink to &quot;Tuning guidance&quot;">​</a></h2><h3 id="verify-max-time-ms-default-30000" tabindex="-1"><code>verify.max-time-ms</code> (default 30000) <a class="header-anchor" href="#verify-max-time-ms-default-30000" aria-label="Permalink to &quot;`verify.max-time-ms` (default 30000)&quot;">​</a></h3><p>The total budget covers everything: the fake CONFIG phase on 1.20.2+, the teleport round-trip, the fall itself (a 200-block fall is ~4 seconds) and any free resets. 30 seconds fits a 500 ms ping with headroom. Raise it for high-latency audiences; lowering it below ~10 seconds risks timing out real players mid-fall.</p><h3 id="verify-only-during-attack-default-false" tabindex="-1"><code>verify.only-during-attack</code> (default false) <a class="header-anchor" href="#verify-only-during-attack-default-false" aria-label="Permalink to &quot;`verify.only-during-attack` (default false)&quot;">​</a></h3><p>With the default, every new address is verified exactly once — after passing, it joins the verified whitelist and skips the fake world for as long as the entry lives (<code>[whitelist] survive-days</code>, 30 days by default), so the steady-state cost is one fall per new player per month. Set <code>only-during-attack = true</code> to skip verification in peace time and run it only while <a href="/pingless-studios-docs/nitrocord/architecture/attack-mode">attack mode</a> is engaged. That trades first-join friction for a smaller peace-time surface — but note that an address first seen <em>during</em> an attack is then checked under attack conditions, when your join pipeline is busiest.</p><h3 id="verify-spawn-height-default-200" tabindex="-1"><code>verify.spawn-height</code> (default 200) <a class="header-anchor" href="#verify-spawn-height-default-200" aria-label="Permalink to &quot;`verify.spawn-height` (default 200)&quot;">​</a></h3><p>Higher falls sample more physics ticks and are strictly harder to fake, at a few extra seconds per verification. The value is clamped to 32–250 (the fake world is 256 blocks high). The default is already far beyond what a bot can bluff; there is little reason to change it.</p><h3 id="geyser-behavior" tabindex="-1">Geyser behavior <a class="header-anchor" href="#geyser-behavior" aria-label="Permalink to &quot;Geyser behavior&quot;">​</a></h3><p>Bedrock clients cannot emulate Java movement physics and would fail every time, so with <code>verify.geyser-skip = true</code> (default) and Geyser/Floodgate detected, Bedrock players skip the check entirely — the same exemption the nickname and account checks already use. Turn the skip off only if your setup routes Java clients through something that fakes the Bedrock username prefix.</p><h3 id="the-verified-whitelist-integration" tabindex="-1">The verified-whitelist integration <a class="header-anchor" href="#the-verified-whitelist-integration" aria-label="Permalink to &quot;The verified-whitelist integration&quot;">​</a></h3><p>Passing the check calls the same <code>WhitelistService</code> a completed login uses: the address is remembered for <code>[whitelist] survive-days</code> (default 30 days) and skips the fall check — and every other accept-time gate — on later joins. Marking an address verified also lifts any active firewall ban on it and wipes its violation history. Your regulars pay for the fall check exactly once a month; only genuinely new addresses fall.</p><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/nitrocord/architecture/overview">Architecture Overview →</a> — the three lifecycle gates a connection passes before verification.</li><li><a href="/pingless-studios-docs/nitrocord/architecture/attack-mode">Attack Mode →</a> — the state machine <code>only-during-attack</code> binds to, and the likeliness scoring that runs alongside.</li><li><a href="/pingless-studios-docs/nitrocord/configuration/reference#verify">Configuration Reference →</a> — every <code>verify.*</code> and <code>invariants.*</code> key.</li></ul>',31))])}const w=r(f,[["render",p]]);export{b as __pageData,w as default};
